import React, {useEffect} from 'react';
import BannerArea from '../components/Homepage/HeroSection/BannerArea';
import UniversitySection from "../components/Homepage/University/UniveristyArea";
import AboutArea from "../components/Homepage/About/AboutArea";
import Navbar from "../components/Navbar";
import Footer from "../components/Homepage/Footer";
import ReactGA from "react-ga";

function Home(props) {

    const {professorList, onChangeProfessor, professor, isHome} = props;
    return (
        <>
            <div>
                <Navbar isHome={isHome}/>
                <HeroSection professorList={professorList} onChangeProfessor={onChangeProfessor} professor={professor}/>
                <AboutArea/>
                <UniversitySection/>
                <Footer/>
            </div>

        </>
    );
}

export default Home;
